func (v InstalledByValue) Equal(o attr.Value) bool {
	other, ok := o.(InstalledByValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.AvatarUrl.Equal(other.AvatarUrl) {
		return false
	}

	if !v.Email.Equal(other.Email) {
		return false
	}

	if !v.Id.Equal(other.Id) {
		return false
	}

	if !v.Kind.Equal(other.Kind) {
		return false
	}

	if !v.Username.Equal(other.Username) {
		return false
	}

	return true
}

func (v InstalledByValue) Type(ctx context.Context) attr.Type {
	return InstalledByType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

